body.script:
(function () {
  "use strict";

  const RAW_URL = "https://raw.githubusercontent.com/hackz00/classroommaxxing/refs/heads/main/index.html";
  const RAW_BASE = new URL(".", RAW_URL).href;

  const iframe = document.getElementById("loadedPage");
  const loadingLabel = document.getElementById("loadingLabel");
  const loadError = document.getElementById("loadError");
  let activeObjectUrl = "";

  function isAbsoluteOrSpecialUrl(value) {
    const url = String(value || "").trim();
    return (
      url === "" ||
      url.startsWith("#") ||
      url.startsWith("//") ||
      /^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(url)
    );
  }

  function absolutize(value) {
    if (isAbsoluteOrSpecialUrl(value)) return value;

    try {
      return new URL(value, RAW_BASE).href;
    } catch (_) {
      return value;
    }
  }

  function rewriteSrcset(value) {
    return String(value || "")
      .split(",")
      .map(function (candidate) {
        const parts = candidate.trim().split(/\s+/);
        const url = parts.shift();

        if (!url) return "";

        const descriptor = parts.join(" ");
        const absoluteUrl = absolutize(url);

        return descriptor ? absoluteUrl + " " + descriptor : absoluteUrl;
      })
      .filter(Boolean)
      .join(", ");
  }

  function rewriteCssUrls(cssText) {
    return String(cssText || "").replace(
      /url\(\s*(['"]?)(?!data:|blob:|https?:|\/\/|#)([^'")]+)\1\s*\)/gi,
      function (_, quote, url) {
        return "url(" + quote + absolutize(url.trim()) + quote + ")";
      }
    );
  }

  function prepareHtml(htmlText) {
    const parser = new DOMParser();
    const doc = parser.parseFromString(htmlText, "text/html");

    if (!doc.documentElement) {
      throw new Error("Remote HTML did not parse as a document.");
    }

    if (!doc.head) {
      const head = doc.createElement("head");
      doc.documentElement.insertBefore(head, doc.body || null);
    }

    if (!doc.body) {
      doc.documentElement.appendChild(doc.createElement("body"));
    }

    doc.querySelectorAll("base").forEach(function (base) {
      base.remove();
    });

    const base = doc.createElement("base");
    base.href = RAW_BASE;
    doc.head.insertBefore(base, doc.head.firstChild);

    const fontPreconnectA = doc.createElement("link");
    fontPreconnectA.rel = "preconnect";
    fontPreconnectA.href = "https://fonts.googleapis.com";
    doc.head.appendChild(fontPreconnectA);

    const fontPreconnectB = doc.createElement("link");
    fontPreconnectB.rel = "preconnect";
    fontPreconnectB.href = "https://fonts.gstatic.com";
    fontPreconnectB.crossOrigin = "anonymous";
    doc.head.appendChild(fontPreconnectB);

    const fontStylesheet = doc.createElement("link");
    fontStylesheet.rel = "stylesheet";
    fontStylesheet.href = "https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&display=swap";
    doc.head.appendChild(fontStylesheet);

    doc.querySelectorAll("[src],[href],[action],[poster],[data-src],[data-href],[srcset]").forEach(function (el) {
      ["src", "href", "action", "poster", "data-src", "data-href"].forEach(function (attr) {
        if (el.hasAttribute(attr)) {
          el.setAttribute(attr, absolutize(el.getAttribute(attr)));
        }
      });

      if (el.hasAttribute("srcset")) {
        el.setAttribute("srcset", rewriteSrcset(el.getAttribute("srcset")));
      }
    });

    doc.querySelectorAll("style").forEach(function (style) {
      style.textContent = rewriteCssUrls(style.textContent);
    });

    doc.querySelectorAll("[style]").forEach(function (el) {
      el.setAttribute("style", rewriteCssUrls(el.getAttribute("style")));
    });

    const shellFixes = doc.createElement("style");
    shellFixes.textContent = [
      "html,body{margin:0;min-width:100%;min-height:100%;font-family:\"IBM Plex Sans\",Arial,sans-serif;}",
      "img,video,canvas,svg,iframe{max-width:100%;}",
      "*{box-sizing:border-box;}"
    ].join("\n");
    doc.head.appendChild(shellFixes);

    return "<!doctype html>\n" + doc.documentElement.outerHTML;
  }

  fetch(RAW_URL, { cache: "no-store" })
    .then(function (response) {
      if (!response.ok) {
        throw new Error("HTTP " + response.status + " " + response.statusText);
      }

      return response.text();
    })
    .then(function (htmlText) {
      const preparedHtml = prepareHtml(htmlText);
      const blob = new Blob([preparedHtml], { type: "text/html;charset=utf-8" });

      if (activeObjectUrl) {
        URL.revokeObjectURL(activeObjectUrl);
      }

      activeObjectUrl = URL.createObjectURL(blob);
      iframe.src = activeObjectUrl;
      loadingLabel.style.display = "none";
    })
    .catch(function (error) {
      loadingLabel.textContent = "Load failed";
      loadError.style.display = "block";
      loadError.textContent = "Failed to load remote HTML.\n\n" + (error && error.message ? error.message : String(error));
    });
})();
